import{_ as t,o as i,c as a,a3 as s}from"./chunks/framework.B5WAEDB7.js";const u=JSON.parse('{"title":"Adding to the settings screen","description":"Add custom entries like privacy policy or imprint through the \\"settings\\" Grid.","frontmatter":{"title":"Adding to the settings screen","description":"Add custom entries like privacy policy or imprint through the \\"settings\\" Grid."},"headers":[],"relativePath":"en/apptiveteams/einstellungen.md","filePath":"en/apptiveteams/einstellungen.md","lastUpdated":1787319236000}'),r={name:"en/apptiveteams/einstellungen.md"};function o(n,e,d,l,c,h){return i(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="adding-to-the-settings-screen" tabindex="-1">Adding to the settings screen <a class="header-anchor" href="#adding-to-the-settings-screen" aria-label="Permalink to &quot;Adding to the settings screen&quot;">​</a></h1><p>Using the Grid with the Key <code>settings</code>, you can add custom entries to the app&#39;s settings screen — for example links to a privacy policy, imprint, or your help section. Every row becomes an entry that opens the stored address when tapped.</p><h2 id="the-fields" tabindex="-1">The fields <a class="header-anchor" href="#the-fields" aria-label="Permalink to &quot;The fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field Key</th><th>Field type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>title</code></td><td>Text</td><td>yes</td><td>Label of the entry</td></tr><tr><td><code>url</code></td><td>Weblink</td><td>yes</td><td>Address opened when tapped</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">The field Key here is <code>url</code>, not <code>uri</code></p><p>In the <code>tabs</code> and <code>TilesGrid</code> Grids, the address field is called <code>uri</code>. In the <code>settings</code> Grid, it&#39;s called <code>url</code>. If you copy fields over from another Grid, it&#39;s easy to carry over the wrong Key — and the entry then simply won&#39;t appear.</p></div><h2 id="what-s-always-there" tabindex="-1">What&#39;s always there <a class="header-anchor" href="#what-s-always-there" aria-label="Permalink to &quot;What&#39;s always there&quot;">​</a></h2><p>Regardless of your configuration, the settings screen always includes:</p><ul><li>the signed-in person&#39;s profile</li><li><strong>Sign out</strong></li><li><strong>Switch team</strong></li><li>the app version</li><li>the option to delete your own account</li></ul><div class="tip custom-block"><p class="custom-block-title">The usual place for legal notices</p><p>A privacy policy and an imprint are generally required for an app you distribute to your workforce. The settings screen is where users expect to find them — and it&#39;s what the app stores check for.</p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/apptiveteams/team-space">Setting up the Team Space</a></li><li><a href="/en/apptiveteams/tabs">Setting up tabs</a></li><li><a href="/en/apptiveteams/fehlerbehebung">Tips and troubleshooting</a></li></ul>',11)])])}const g=t(r,[["render",o]]);export{u as __pageData,g as default};
